import react from '@vitejs/plugin-react'
import { defineConfig } from 'vite'
import { VitePWA } from 'vite-plugin-pwa'

// https://vite.dev/config/
export default defineConfig({
  plugins: [
    react(),
    // Service worker + web manifest. The worker is (re)generated by scripts/prerender.mjs AFTER the
    // prerendered pages exist, through this plugin's api.generateSW() - the copy written during
    // `vite build` itself only sees Vite's own output. Registration lives in src/main.tsx (a plain
    // navigator.serviceWorker.register on `load`), not an injected snippet, so every prerendered
    // page registers it by virtue of loading the bundle.
    VitePWA({
      strategies: 'generateSW',
      injectRegister: false,
      includeManifestIcons: true,
      manifest: {
        name: 'Pariksha Saathi - free SSC, IBPS & SBI exam prep',
        short_name: 'Pariksha Saathi',
        description:
          'Free exam prep for SSC, banking, railway, police and state PSC exams: lessons, practice quizzes, mock tests and dated current affairs, in English and Hindi.',
        lang: 'en',
        start_url: '/',
        scope: '/',
        display: 'standalone',
        // theme.css tokens: --navy (header/hero) and --paper (page background).
        theme_color: '#1e3a52',
        background_color: '#faf7f2',
        icons: [
          { src: '/assets/icon-192.png', sizes: '192x192', type: 'image/png' },
          { src: '/assets/icon-512.png', sizes: '512x512', type: 'image/png' },
        ],
      },
      workbox: {
        // Precache = what a first visit should leave behind so the site opens offline next time:
        // the home page and SPA shell, the top-level public pages, the entry bundle, the two latin
        // font files every page needs, the icons and the small hero image variants. Deliberately
        // NOT the ~700 prerendered articles, the multi-megabyte lesson/current-affairs data chunks
        // or anything under /pdf/ - those are cached at runtime, once a visitor actually opens them.
        globPatterns: [
          'index.html',
          // The prerendered pages exist only once scripts/prerender.mjs has run; it sets
          // PWA_PRERENDERED before regenerating the worker. Listing them during `vite build` itself
          // would only produce "glob matched nothing" warnings.
          ...(process.env.PWA_PRERENDERED
            ? [
                'spa.html',
                '404.html',
                '{learn,exams,about,privacy,terms,contact,downloads,account-deletion,onboarding}/index.html',
                'hi/index.html',
                'hi/{learn,exams}/index.html',
              ]
            : []),
          'assets/index-*.js',
          'assets/jsx-runtime-*.js',
          'fonts/fraunces-latin-v*.woff2',
          'fonts/ibm-plex-sans-latin-v*.woff2',
          'assets/screenshots/1-home-{240,480}.webp',
        ],
        globIgnores: ['pdf/**'],
        // Vite's hashed /assets/* names are already unique per content.
        dontCacheBustURLsMatching: /^assets\/.+-[\w-]{8}\.(?:js|css)$/,
        // Never answer a navigation from the precached shell when online - the prerendered HTML on
        // the network is the canonical page. Offline fallback is handled per route below.
        navigateFallback: null,
        cleanupOutdatedCaches: true,
        clientsClaim: true,
        skipWaiting: false,
        runtimeCaching: [
          {
            // Page navigations: network first (fresh HTML, fresh asset hashes), the last copy from
            // cache when offline, and the SPA shell as a last resort so client-side routes such as
            // /app/* still open offline. PDFs are excluded so a 3 MB download never lands in cache.
            urlPattern: ({ request, url, sameOrigin }) =>
              sameOrigin && request.mode === 'navigate' && !url.pathname.startsWith('/pdf/') && url.pathname !== '/daily-pdf',
            handler: 'NetworkFirst',
            options: {
              cacheName: 'pages',
              networkTimeoutSeconds: 4,
              expiration: { maxEntries: 150, maxAgeSeconds: 30 * 24 * 60 * 60 },
              cacheableResponse: { statuses: [200] },
              precacheFallback: { fallbackURL: '/spa.html' },
            },
          },
          {
            // Hashed build output and the versioned fonts: immutable, so cache first.
            urlPattern: ({ url, sameOrigin }) =>
              sameOrigin && (url.pathname.startsWith('/assets/') || url.pathname.startsWith('/fonts/')),
            handler: 'CacheFirst',
            options: {
              cacheName: 'static',
              expiration: { maxEntries: 300, maxAgeSeconds: 365 * 24 * 60 * 60 },
              cacheableResponse: { statuses: [200] },
            },
          },
          {
            // Public, anonymous JSON from the content API (current affairs, notices, exam facts,
            // lessons, questions). Anything authenticated or account-related is never cached.
            urlPattern: ({ url, request }) =>
              url.origin === 'https://api.parikshasaathi.com' &&
              url.pathname.startsWith('/v1/') &&
              !url.pathname.startsWith('/v1/auth') &&
              !url.pathname.startsWith('/v1/progress') &&
              !request.headers.has('authorization'),
            handler: 'NetworkFirst',
            options: {
              cacheName: 'api',
              networkTimeoutSeconds: 6,
              expiration: { maxEntries: 200, maxAgeSeconds: 7 * 24 * 60 * 60 },
              cacheableResponse: { statuses: [200] },
            },
          },
        ],
      },
    }),
  ],
})
